-- ============================================================================================
-- SITES : renseigner la ville et le departement
-- ============================================================================================
-- Demande de Naoelle du 15/08/2026 : « il faut que tous les sites aient une ville renseignee ».
-- Constat de depart : sur 6356 sites, 318 seulement portaient une ville, et AUCUN ne portait de
-- departement — les colonnes departement_code et departement_nom etaient vides sur la totalite
-- des lignes. La colonne « Ville » de la liste des sites etait donc vide dans 95 % des cas.
--
-- DEUX SOURCES, choisies pour leur fiabilite respective.
--
-- 1. Le departement se deduit du code postal, sans rien interroger d'exterieur : 6098 sites en ont
--    un. La regle est celle de l'INSEE — deux premiers chiffres, sauf la Corse (20000-20199 en 2A,
--    au-dela en 2B) et l'outre-mer (trois chiffres). C'est arithmetique, donc sur.
--
-- 2. La ville vient d'un geocodage inverse des coordonnees par l'API BAN (adresse.data.gouv.fr),
--    le service public francais d'adresses : gratuit, sans compte, et seules des coordonnees lui
--    sont soumises. Le code postal seul ne suffisait pas — une commune par code postal n'est pas
--    garantie — alors que les coordonnees designent un point unique.
--
--    Qualite mesuree avant de s'en servir, sur 200 sites dont la ville etait DEJA connue :
--      ville identique au caractere pres  187/198
--      code postal identique              197/198
--      sans reponse                       2
--    Les 11 ecarts sont des variantes d'ecriture ou des communes fusionnees, pas des erreurs de
--    localisation. Aucune ville deja renseignee n'est touchee : la mise a jour ne vise que les
--    sites dont la ville est vide, et un garde-fou ecarte toute reponse dont le departement ne
--    correspondrait pas au code postal du site (aucune ligne ecartee sur ce lot).
--
--    Les villes sont ecrites en MAJUSCULES sans accent, pour s'aligner sur l'existant : 301 des
--    318 villes deja renseignees le sont, et « PARIS » y figure 41 fois contre « Paris » une. Les
--    arrondissements rendus par la BAN (« Paris 14e Arrondissement ») sont ramenes a la commune,
--    le code postal les portant deja.
--
-- COUVERTURE. 5432 villes sur les 6038 sites qui en manquaient. Les ~600 restants n'ont pas de
-- coordonnees : ils resteront sans ville jusqu'a ce qu'on les geolocalise ou qu'on saisisse
-- l'adresse. Le departement, lui, sera renseigne partout ou il y a un code postal.
-- ============================================================================================

begin;

-- --------------------------------------------------------------------------------------------
-- 1. Le departement, deduit du code postal
-- --------------------------------------------------------------------------------------------
