    ('94', 'Val-de-Marne'),
    ('95', 'Val-d''Oise'),
    ('971', 'Guadeloupe'),
    ('972', 'Martinique'),
    ('973', 'Guyane'),
    ('974', 'La Réunion'),
    ('976', 'Mayotte'),
    ('01', 'Ain'),
    ('02', 'Aisne'),
    ('03', 'Allier'),
    ('04', 'Alpes-de-Haute-Provence'),
    ('05', 'Hautes-Alpes'),
    ('06', 'Alpes-Maritimes'),
    ('07', 'Ardèche'),
    ('08', 'Ardennes'),
    ('09', 'Ariège'),
    ('2A', 'Corse-du-Sud'),
    ('2B', 'Haute-Corse')
),
calcul as (
  select s.id,
         case
           -- Outre-mer : les codes 97x et 98x tiennent sur trois chiffres.
           when left(btrim(s.code_postal), 2) in ('97', '98') then left(btrim(s.code_postal), 3)
           -- Corse : un seul code postal 20xxx pour deux departements.
           when left(btrim(s.code_postal), 2) = '20'
             then case when btrim(s.code_postal)::int < 20200 then '2A' else '2B' end
           else left(btrim(s.code_postal), 2)
         end as code
  from sites s
  where btrim(coalesce(s.code_postal, '')) ~ '^[0-9]{5}$'
)
update public.sites s
   set departement_code = c.code,
       departement_nom  = d.nom,
       date_modification = now()
  from calcul c
  left join departements d on d.code = c.code
 where s.id = c.id
   and (s.departement_code is distinct from c.code);

