update public.sites s
   set ville = v.ville,
       date_modification = now()
  from villes v
 where s.id = v.site_id
   and btrim(coalesce(s.ville, '')) = '';

commit;

-- ============================================================================================
-- CONTROLE APRES APPLICATION
-- ============================================================================================
--   select count(*) total,
--          count(*) filter (where btrim(coalesce(ville,'')) <> '') avec_ville,
--          count(departement_code) avec_departement
--   from sites;
--
-- Attendu : 6356 sites, environ 5750 avec une ville (318 + 5432), et 6098 avec un departement.
-- Les sites restes sans ville sont ceux qui n'ont pas de coordonnees :
--   select count(*) from sites where btrim(coalesce(ville,'')) = '' and latitude is null;
